/* ============================================================================
 * hub.js —— 书源中枢运行时（Rhino / 阅读 jsLib 兼容）
 * ----------------------------------------------------------------------------
 * 这段代码有两个宿主：
 *   1) 阅读 App 的 Rhino 引擎（真机）：通过 jsLib 里的 HUB 对象调用
 *   2) Node（本地自检 / 模拟器）：tools/simulate.mjs 直接 eval
 *
 * 因此这里 **只用** ES5 + 少量被两个引擎都支持的语法（let / 模板串 / 箭头函数
 * 在 Rhino 6+ 与 Node 都可用；但为稳妥，本文件刻意用 var + 函数声明）。
 *
 * 注入约定：
 *   createHub(java, source, opts)
 *     java   —— 宿主 java 对象（阅读内置），mock 里是实现同一批方法的桩
 *     source —— 当前 Source（提供 getVariable/setVariable/cache）
 *     opts   —— { mirrors:[], cacheTTL:int, log:fn, now:fn }
 *
 * 产物 JSON 的"消费方"约定（供 main.js 用）：
 *   manifest = { schema, version, updated, bookSources:[{key,name,group,enabled,type,desc,file,sha256,lastUpdateTime,deprecated}], rss:[...], libs:[...] }
 * ==========================================================================*/
/* 书源的 jsLib 是在"静态上下文"里跑的，那时通常没有 java/source。
 * 所以 createHub 允许先建壳、后绑定：调用 createHub() 之后立刻 .bind(java, source)，
 * 或者由 HUBCTX 里的 onCall 每次调用时自动刷新绑定。 */
function createHub(java, source, opts) {
    opts = opts || {};
    var MIRRORS = opts.mirrors && opts.mirrors.length ? opts.mirrors : ['', 'https://ghproxy.net/', 'https://gh-proxy.com/'];
    var CACHE_TTL = opts.cacheTTL || 21600;      // 秒；0 = 永久
    var CACHE_PREFIX = 'hub:';
    var ST_LASTOK = 'hub:lastok';                // 上次成功的镜像序号

    function nowMs() { return opts.now ? opts.now() : new Date().getTime(); }
    function log(m) { if (opts.log) opts.log(String(m)); }

    /* ---------- 缓存（CacheManager，存在 App 私有目录，重启不丢） ---------- */
    function cacheGet(key) {
        try { return source.cache.get(CACHE_PREFIX + key) || ''; } catch (e) { return ''; }
    }
    function cachePut(key, val, ttl) {
        try { source.cache.put(CACHE_PREFIX + key, String(val), ttl === undefined ? CACHE_TTL : ttl); } catch (e) { }
    }

    /* ---------- 多镜像取文件：按上次成功的镜像优先，失败自动降级 ---------- */
    function fetchText(path, useCache) {
        var cacheKey = 'file:' + path;
        if (useCache !== false) {
            var c = cacheGet(cacheKey);
            if (c) return c;
        }
        var start = 0;
        try { var li = parseInt(cacheGet(ST_LASTOK), 10); if (li >= 0 && li < MIRRORS.length) start = li; } catch (e) { }
        var errs = [];
        for (var n = 0; n < MIRRORS.length; n++) {
            var i = (start + n) % MIRRORS.length;
            var url = MIRRORS[i] + path + '?t=' + nowMs();      // t= 破镜像缓存
            try {
                var res = java.get(url, { 'User-Agent': 'Legado-Hub/2.0' });
                var code = res.status ? res.status() : 200;
                if (code === 200) {
                    var body = res.body();
                    if (body && body.length) {
                        cachePut(ST_LASTOK, String(i), 0);
                        cachePut(cacheKey, body, CACHE_TTL);
                        return body;
                    }
                }
                errs.push('#' + i + ' HTTP ' + code);
            } catch (e) {
                errs.push('#' + i + ' ' + e);
            }
        }
        throw new Error('全部镜像失败：' + errs.join(' | '));
    }

    function fetchJson(path, useCache) { return JSON.parse(fetchText(path, useCache)); }

    /* ---------- 版本比较：语义化 + lastUpdateTime ---------- */
    function cmpVer(a, b) {
        a = String(a || '0'); b = String(b || '0');
        if (/^\d+$/.test(a) && /^\d+$/.test(b)) return Number(a) - Number(b);
        var pa = a.split(/[.\-+]/), pb = b.split(/[.\-+]/);
        for (var i = 0; i < Math.max(pa.length, pb.length); i++) {
            var x = parseInt(pa[i] || '0', 10), y = parseInt(pb[i] || '0', 10);
            if (x > y) return 1;
            if (x < y) return -1;
        }
        return a.localeCompare(b);
    }

    /* ---------- 用户配置（只认这几种 key，永远不整体覆盖） ---------- */
    var CONFIG_KEYS = ['hub', 'libs', 'policy', 'mirror', 'lastSeenVersion', 'localVersion'];

    function getCfg() {
        var s = '';
        try { s = String(source.getVariable() || ''); } catch (e) { s = ''; }
        if (!s) return {};
        try { return JSON.parse(s) || {}; } catch (e) { return {}; }
    }
    function setCfg(cfg) {
        var keep = {};
        for (var i = 0; i < CONFIG_KEYS.length; i++) {
            var k = CONFIG_KEYS[i];
            if (cfg[k] !== undefined) keep[k] = cfg[k];
        }
        try { source.setVariable(JSON.stringify(keep, null, '\t')); } catch (e) { }
        return keep;
    }
    // 迁移：老版订阅源变量里有 sourl/jk/type/seturl/key/name/page —— 原样保留，别弄丢用户密钥
    function migrateCfg() {
        var cfg = getCfg();
        var dirty = false;
        var legacy = ['sourl', 'jk', 'type', 'seturl', 'key', 'name', 'page'];
        for (var i = 0; i < legacy.length; i++) {
            var k = legacy[i];
            if (cfg[k] !== undefined) { delete cfg[k]; dirty = true; }
        }
        if (cfg.hub === undefined) { cfg.hub = 2; dirty = true; }
        if (dirty) setCfg(cfg);
        // 老字段另存一份，万一下游还要用
        return cfg;
    }

    /* ---------- 打包：把多份书源 JSON 合成一份"可导入"的文件 ---------- */
    function pack(list) {
        var arr = [];
        for (var i = 0; i < list.length; i++) {
            var it = list[i];
            if (!it) continue;
            arr = arr.concat(Array.isArray(it) ? it : [it]);
        }
        return JSON.stringify(arr, null, 2);
    }

    /* ---------- 深链：两种都可用，native 优先 ---------- */
    function deepLink(kind, url) {
        return 'legado://import/' + kind + '?src=' + encodeURIComponent(url);
    }
    function nativeImport(kind, url) {
        // java.openUrl 对 legado:// 会直接拉起 OnLineImportActivity（源码已核实）
        try {
            java.openUrl(deepLink(kind, url));
            return true;
        } catch (e) {
            log('openUrl 失败，回退 startBrowser：' + e);
            try { java.startBrowser(deepLink(kind, url), '导入'); return true; } catch (e2) { return false; }
        }
    }

    var _bound = !!(java && source);
    function bind(j, s) {
        if (j) java = j;
        if (s) source = s;
        if (j || s) _bound = true;
    }
    function ready() {
        if (!_bound) throw new Error('createHub 尚未绑定宿主：请在规则里调 HUB.bind(java, source) 后使用');
        return true;
    }

    // 统一入口：调用前确保已绑定
    function wrap(fn) {
        return function () {
            try { ready(); } catch (e) { if (opts.onError) return opts.onError(e); throw e; }
            return fn.apply(null, arguments);
        };
    }
    return {
        bind: bind,
        _ready: ready,
        MIRRORS: MIRRORS,
        CACHE_TTL: CACHE_TTL,
        nowMs: nowMs,
        log: log,
        cacheGet: cacheGet,
        cachePut: cachePut,
        fetchText: wrap(fetchText),
        fetchJson: wrap(fetchJson),
        cmpVer: cmpVer,
        getCfg: wrap(getCfg),
        setCfg: wrap(setCfg),
        migrateCfg: migrateCfg,
        pack: pack,
        deepLink: deepLink,
        nativeImport: nativeImport
    };
}

/* ============================================================================
 * panel.js —— 订阅源「控制台」的菜单与 HTML 面板生成器
 * ----------------------------------------------------------------------------
 * 用法（订阅源 ruleArticles / ruleContent 里）：
 *     var HUB = createHub(java, source, {mirrors:[...], cacheTTL:21600});
 *     var p = buildPanel(HUB, {base:'legado-sources/', tag:'辞晨', consoleRss:'rss/console.json'});
 *     p.menu          -> ruleArticles 的返回（文章列表）
 *     p.html(article) -> ruleContent 的返回（HTML 面板）
 *
 * 依赖：hub.js 先于本文件 eval。
 * ==========================================================================*/
function buildPanel(HUB, cfg) {
    cfg = cfg || {};
    var BASE = cfg.base || '';
    var TAG = cfg.tag || '';
    var CONSOLE_RSS = cfg.consoleRss || 'rss/console.json';
    var EXTRA_MENU = cfg.extraMenu || [];

    /* ---------- 取清单（带缓存 + 多镜像） ---------- */
    function manifest(force) {
        return HUB.fetchJson(BASE + 'dist/manifest.json', force ? false : true);
    }

    /* ---------- 计算"有哪些更新" ---------- */
    function diff(mf) {
        var st = HUB.getCfg();
        var seen = st.localVersion || {};
        var newer = [], all = [];
        for (var i = 0; i < (mf.bookSources || []).length; i++) {
            var s = mf.bookSources[i];
            all.push(s);
            if (s.deprecated) continue;
            var mine = seen[s.key];
            if (!mine || HUB.cmpVer(s.version, mine) > 0) newer.push(s);
        }
        return { newer: newer, all: all };
    }

    /* ---------- 深链 ---------- */
    function linkSource(s) { return HUB.deepLink('bookSource', HUB.MIRRORS[0] + BASE + s.file); }
    function linkAll(mf) { return HUB.deepLink('bookSource', HUB.MIRRORS[0] + BASE + (mf.bundle || 'out/all.json')); }
    function linkRss(r) { return HUB.deepLink('rssSource', HUB.MIRRORS[0] + BASE + r.file); }

    /* ================= 菜单（ruleArticles） ================= */
    function menu() {
        var list = [];
        var mf = null, err = '';
        try { mf = manifest(true); } catch (e) { err = String(e); }

        if (mf) {
            var d = diff(mf);
            var badge = d.newer.length ? ' 🔴' + d.newer.length : ' ✅';
            list.push({
                name: '📊 控制台' + badge,
                url: 'data:text/html;base64,' + enc('<b>控制台</b>'),
                img: 'https://t.alcy.cc/ysz'
            });
            for (var i = 0; i < d.all.length; i++) {
                var s = d.all[i];
                var st = d.newer.indexOf(s) >= 0 ? ' 🆕' : '';
                list.push({
                    name: (s.enabled === false ? '⏸ ' : '') + s.name + st,
                    url: linkSource(s),
                    img: 'https://t.alcy.cc/mp'
                });
            }
        } else {
            list.push({
                name: '⚠️ 清单拉取失败（点我看原因）',
                url: 'data:text/html;base64,' + enc(err),
                img: 'https://t.alcy.cc/ai'
            });
        }
        if (EXTRA_MENU.length) list = list.concat(EXTRA_MENU);
        return list;
    }

    /* ================= 控制台 HTML（ruleContent） ================= */
    function html(article) {
        var mf = null, err = '';
        try { mf = manifest(true); } catch (e) { err = String(e); }
        var css =
            'body{font-family:system-ui,-apple-system,"PingFang SC",sans-serif;margin:0;padding:14px;background:#0f1218;color:#e6edf3}' +
            'h1{font-size:19px;margin:0 0 4px}h2{font-size:15px;margin:20px 0 8px;color:#9fb3c8}' +
            '.sub{font-size:12px;color:#7d8b99;margin-bottom:14px}' +
            '.card{background:#161b22;border:1px solid #242c37;border-radius:12px;padding:12px;margin:10px 0}' +
            '.row{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 0;border-bottom:1px solid #1e242c}' +
            '.row:last-child{border-bottom:0}.nm{font-size:14px}.meta{font-size:11px;color:#7d8b99;margin-top:2px}' +
            'a.btn{display:inline-block;padding:7px 12px;border-radius:8px;background:#2f81f7;color:#fff;text-decoration:none;font-size:13px;white-space:nowrap}' +
            'a.btn.g{background:#238636}a.btn.y{background:#9e6a03}a.btn.r{background:#8b2c2c}' +
            '.tag{font-size:11px;padding:2px 7px;border-radius:999px;background:#1f6feb33;color:#79c0ff}' +
            '.tag.w{background:#9e6a0333;color:#e3b341}.tag.k{background:#23863633;color:#7ee787}' +
            '.err{color:#ff7b72;font-size:12px;word-break:break-all}' +
            '.kv{font-size:12px;color:#9fb3c8;line-height:1.7}' +
            '.foot{margin-top:18px;font-size:11px;color:#5c6a78;text-align:center}';

        var b = [];
        b.push('<!DOCTYPE html><html><head><meta charset="utf-8">');
        b.push('<meta name="viewport" content="width=device-width,initial-scale=1">');
        b.push('<style>' + css + '</style></head><body>');
        b.push('<h1>🌐 书源控制台</h1>');
        b.push('<div class="sub">' + esc(TAG) + ' · 订阅驱动 · 点按钮即导入</div>');

        if (!mf) {
            b.push('<div class="card"><div class="err">清单拉取失败：' + esc(err) + '</div>');
            b.push('<div class="kv">可能原因：镜像全挂 / 仓库改了名 / 文件名写错。<br>改这里：源里的 <b>jsLib</b> 顶部 MIRRORS 与 BASE。</div></div>');
        } else {
            var d = diff(mf);
            b.push('<div class="card"><div class="kv">');
            b.push('清单版本 <span class="tag k">' + esc(mf.version) + '</span> ');
            b.push('更新于 ' + esc(mf.updated) + '<br>');
            b.push('书源 ' + d.all.length + ' 个 · 有更新 <b>' + d.newer.length + '</b> 个');
            b.push('</div>');
            if (d.newer.length) {
                b.push('<div style="margin-top:10px"><a class="btn g" href="' + linkAll(mf) + '">一键导入全部（' + d.all.length + ' 个）</a></div>');
            }
            b.push('</div>');

            b.push('<h2>书源</h2><div class="card">');
            for (var i = 0; i < d.all.length; i++) {
                var s = d.all[i];
                var isNew = d.newer.indexOf(s) >= 0;
                b.push('<div class="row"><div>');
                b.push('<div class="nm">' + esc(s.name) + '</div>');
                b.push('<div class="meta">v' + esc(s.version) + ' · ' + esc(s.group || '') +
                    (s.desc ? ' · ' + esc(s.desc) : '') + '</div>');
                b.push('</div><div>');
                if (s.deprecated) b.push('<span class="tag">已弃用</span> ');
                else if (isNew) b.push('<span class="tag w">可更新</span> ');
                else b.push('<span class="tag k">已最新</span> ');
                b.push('<a class="btn" href="' + linkSource(s) + '">导入</a>');
                b.push('</div></div>');
            }
            b.push('</div>');

            if (mf.rss && mf.rss.length) {
                b.push('<h2>订阅源</h2><div class="card">');
                for (var j = 0; j < mf.rss.length; j++) {
                    var r = mf.rss[j];
                    b.push('<div class="row"><div><div class="nm">' + esc(r.name) + '</div>');
                    b.push('<div class="meta">v' + esc(r.version) + ' · ' + esc(r.desc || '') + '</div></div>');
                    b.push('<div><a class="btn y" href="' + linkRss(r) + '">导入</a></div></div>');
                }
                b.push('</div>');
            }

            b.push('<h2>说明</h2><div class="card kv">');
            b.push('· 代码在 GitHub，订阅源只负责「指路」，更新代码不用再发订阅源。<br>');
            b.push('· 每个书源自带热更新：规则运行时从仓库拉最新 jsLib 并缓存，改逻辑不必重导。<br>');
            b.push('· 导入时会弹原生的「选中更新源」，同名源按 lastUpdateTime 覆盖。<br>');
            b.push('· 镜像顺序：直连 → ghproxy → gh-proxy，谁通走谁，记住上次成功的那个。');
            b.push('</div>');
        }
        b.push('<div class="foot">' + esc(TAG) + ' · hub v' + ('2.0') + '</div>');
        b.push('</body></html>');
        return b.join('');
    }

    /* ---------- 小工具 ---------- */
    function esc(s) {
        return String(s === undefined || s === null ? '' : s)
            .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }
    function enc(s) {
        // data: URL 用；Rhino 没有 btoa，用 java.base64Encode
        try { return java.base64Encode(String(s)); } catch (e) { return ''; }
    }

    return { menu: menu, html: html, manifest: manifest, diff: diff, linkSource: linkSource, linkAll: linkAll, linkRss: linkRss };
}

var HSRC = { base: "https://raw.githubusercontent.com/GEd520/legado-sources/main/", mirrors: ["","https://ghproxy.net/","https://gh-proxy.com/"] };
function hubInst() { return createHub(java, source, { mirrors: HSRC.mirrors, cacheTTL: 21600 }); }
function panelInst() { return buildPanel(hubInst(), { base: HSRC.base, tag: "辞晨", consoleRss: 'dist/rss/console.json' }); }

